dir:
























































































































































	select data as id into #id from dbo.ISWIFTFunction$Split(@so_ct, ',')
	select top 0 id, line, ma_phi as ma_vt, ma_cong, ma_dk_phi, ma_dvt as dvt,so_luong, gia_nt1 as gia_nt2, tien_nt1 as tien_nt2, ma_nt, ty_gia, gia1 as gia2, tien1 as tien2, line_bg, id_bg into #detail from v61 a
	DECLARE @q NVARCHAR(4000), @id_yc int, @t_luong numeric(19,5),@t_khoi numeric(19,5),@dl_yn int, @ncc_yn int,@ma_hang varchar(32),@ten_hang nvarchar(255),@ma_dl varchar(32), @id_bg int, @ma_ct_bg varchar(32)

	select * into #master1 from s61 where id in (select top 1 id from #id order by id desc)
	select  @ma_ct_bg = ma_ct_bg from #master1

	select * into #masterbq1 from s41 where id in (select id_bg from #master1)
	DELETE #masterbq1 where ma_ct <> @ma_ct_bg
	select * into #detailbq1 from v41 where id in (select id from #masterbq1)

	select * into #masterbq2 from s42 where id in (select id_bg from #master1)
	DELETE #masterbq2 where ma_ct <> @ma_ct_bg
	select * into #detailbq2 from v42 where id in (select id from #masterbq2)

	select * into #masterbq3 from s43 where id in (select id_bg from #master1)
	DELETE #masterbq3 where ma_ct <> @ma_ct_bg
	select * into #detailbq3 from v43 where id in (select id from #masterbq3)

	if @ma_ct_bg = 'BQ1'
	begin
		Set @q = 'insert into #detail select id,line,ma_phi,ma_cong,ma_dk_phi,ma_dvt,so_luong,gia_nt1,tien_nt1,ma_nt,ty_gia,gia1,tien1,line,id from #detailbq1'
		exec(@q);
	end
	if @ma_ct_bg = 'BQ2'
	begin
		Set @q = 'insert into #detail select id,line,ma_phi,ma_cong,ma_dk_phi,ma_dvt,so_luong,gia_nt1,tien_nt1,ma_nt,ty_gia,gia1,tien1,line,id from #detailbq2'
		exec(@q);
	end
	if @ma_ct_bg = 'BQ3'
	begin
		Set @q = 'insert into #detail select id,line,ma_phi,ma_cong,ma_dk_phi,ma_dvt,so_luong,gia_nt1,tien_nt1,ma_nt,ty_gia,gia1,tien1,line,id from #detailbq3'
		exec(@q);
	end

	select a.* ,b.ten_vt,x.ten_dvt,nt.ten_nt, c.id as id_dh from #detail a
	left join s61 c on a.id = c.id_bg
	left join dmvt b on a.ma_vt = b.ma_vt
	left join dmdvt x on a.dvt = x.dvt 
	left join dmnt nt on a.ma_nt = nt.ma_nt
	order by a.line, a.id

	DECLARE @ds_cong VARCHAR(4000)  
	SELECT distinct ma_cong into #tt FROM #detail a
	SELECT @ds_cong = COALESCE(@ds_cong + ', ','') + ltrim(rtrim(ma_cong)) FROM #tt


	if @ma_ct_bg = 'BQ1'
	begin
		select @ds_cong ds_cong, a.dien_giai, a.id id_dh, a.so_job so_job_dh, a.id_bg, a.id_tg, a.so_ct so_ct_dh,
		a.ma_noi_di, a.ma_noi_den, a.ma_hang, a.ma_kh, a.ma_job, a.ma_ct ma_ct_dh ,d.ten_hang, f.ten_kh, b.ten_noi_di, c.ten_noi_den
		from s61 a 
		  left join vdmhangtau d on a.ma_hang = d.ma_hang
		  left join dmkh f on a.ma_kh = f.ma_kh
		  left join vdmcangdi b on a.ma_noi_di = b.ma_noi_di
		  left join vdmcangden c on a.ma_noi_den = c.ma_noi_den
		  left join #masterbq1 m on a.id_bg = m.id
		where a.id in (select top 1 id from #id order by id desc) 	
	end
	if @ma_ct_bg = 'BQ2'
	begin
		select m.t_tong_khoi, m.t_tong_trong, a.dien_giai, a.id id_dh, a.so_job so_job_dh, a.id_bg, a.id_tg, a.so_ct so_ct_dh,
		a.ma_noi_di, a.ma_noi_den, a.ma_hang, a.ma_kh, a.ma_job, a.ma_ct ma_ct_dh ,d.ten_hang, f.ten_kh, b.ten_noi_di, c.ten_noi_den
		from s61 a 
		  left join vdmhangtau d on a.ma_hang = d.ma_hang
		  left join dmkh f on a.ma_kh = f.ma_kh
		  left join vdmcangdi b on a.ma_noi_di = b.ma_noi_di
		  left join vdmcangden c on a.ma_noi_den = c.ma_noi_den
		  left join #masterbq2 m on a.id_bg = m.id
		  where a.id in (select top 1 id from #id order by id desc) 
	end
	if @ma_ct_bg = 'BQ3'
	begin
		select m.t_tong_khoi, m.t_tong_trong, a.dien_giai, a.id id_dh, a.so_job so_job_dh, a.id_bg, a.id_tg, a.so_ct so_ct_dh,
		a.ma_noi_di, a.ma_noi_den, a.ma_hang, a.ma_kh, a.ma_job, a.ma_ct ma_ct_dh ,d.ten_hang, f.ten_kh, b.ten_noi_di, c.ten_noi_den
		from s61 a 
		  left join vdmhangtau d on a.ma_hang = d.ma_hang
		  left join dmkh f on a.ma_kh = f.ma_kh
		  left join vdmcangdi b on a.ma_noi_di = b.ma_noi_di
		  left join vdmcangden c on a.ma_noi_den = c.ma_noi_den
		  left join #masterbq3 m on a.id_bg = m.id
		  where a.id in (select top 1 id from #id order by id desc) 
	end

     drop table #id, #detail, #master1, #masterbq1, #detailbq1,#masterbq2, #detailbq2,#masterbq3, #detailbq3, #tt










  &DefaultButton;




function filter$m45DN1Select(p){
  this.constructor(p);
}
filter$m45DN1Select.prototype = new DirEvent();
filter$m45DN1Select.prototype.beforeInit = function(){
  var p = this._dir;

}


filter$m45DN1Select.prototype.afterInit = function(){
	var p = this._dir,g = p.grid(0),master = g.ds.get(1), rErr = '';
  p.valForm(['ngay_ct1','ngay_ct2','id', 'ma_noi_di', 'ten_noi_di', 'ma_noi_den', 'ten_noi_den', 'ma_nt', 'unit_id'], [p.options._ngay_ct1,p.options._ngay_ct2,p.options._so_ct,p.options._ma_noi_di, p.options._ten_noi_di,p.options._ma_noi_den, p.options._ten_noi_den,  p.options._ma_nt, p.options._unit_id]);
	dir$m45DN1SetMaster(p);

}

function dir$m45DN1SetMaster(p) {
  p.request('ma_kh_request', '', ['id']);
}

filter$m45DN1Select.prototype.beforeAcceptFilter = function (m2, opt, sub) {
  var p = this._dir, pa = p.options.parent, g = p.grid(), dt = g.data, master = g.ds.get(1), rErr = '';

 var fun = function(){
	dt.removeRow('[so_luong] == 0');
    pa.appendGrid(0, dt, p.valForm('xprocess') == "2", 'so_luong', 'so_luong');
	pa.calcExpressionAll(0, 'so_luong');
    pa.appendForm(master, 0);
    p._close();
  }

  if (rErr.length) {
    $.question('$VoucherRetrieveLimit', null, p, function(q, v){
      q._close();
      if (v) fun();
    });
  } else fun();

  //p._close();

  return false;
}









			  		DECLARE @ds_cong VARCHAR(4000)  
					SELECT distinct ma_cong into #tt FROM v61 a where a.id = @id
					SELECT @ds_cong = COALESCE(@ds_cong + ', ','') + ltrim(rtrim(ma_cong)) FROM #tt

					select top 1 a.ma_kh as [!ma_kh],a.ma_hang as [!ma_hang], a.ma_noi_di as [!ma_noi_di], a.ma_noi_den as [!ma_noi_den], 
					@ds_cong as [!ds_cong],b.ten_noi_di as [!ten_noi_di],c.ten_noi_den as [!ten_noi_den],d.ten_kh as [!ten_kh],e.ten_hang as [!ten_hang], a.dien_giai as [!dien_giai]
				  from s61 a 
				  left join vdmcangdi b on a.ma_noi_di =b.ma_noi_di 
				  left join vdmcangden c on a.ma_noi_den =c.ma_noi_den 
				  left join dmkh d on a.ma_kh =d.ma_kh 
				  left join vdmhangtau e on a.ma_hang =e.ma_hang 
				  where a.id = @id
